INSERT INTO cms_content (id,data,change_note) VALUES (1,'{"schemaVersion":1,"cards":[{"id":"N-01","faction":"美国/北约","name":"西柏林驻防分队","type":"步兵","cost":1,"operation_cost":1,"attack":1,"defense":3,"rarity":"普通","effect":"守护。","historical_anchor":"美军冷战驻柏林部队；编制抽象。","fictional":false,"alternate_timeline":false},{"id":"N-02","faction":"美国/北约","name":"第82空降师","type":"步兵","cost":2,"operation_cost":1,"attack":2,"defense":2,"rarity":"普通","effect":"闪击。","historical_anchor":"美国空降部队，采用冷战时期装备。","fictional":false,"alternate_timeline":false},{"id":"N-03","faction":"美国/北约","name":"第101空中突击师","type":"步兵","cost":3,"operation_cost":1,"attack":3,"defense":3,"rarity":"限定","effect":"闪击。部署：另一支友方步兵本回合攻击+1。","historical_anchor":"越战后空中突击编制；不另设直升机兵种。","fictional":false,"alternate_timeline":false},{"id":"N-04","faction":"美国/北约","name":"第75游骑兵团","type":"步兵","cost":3,"operation_cost":1,"attack":3,"defense":2,"rarity":"限定","effect":"伏击。部署：锁定一支敌方地面单位。","historical_anchor":"采用1986年后团级称号。","fictional":false,"alternate_timeline":false},{"id":"N-05","faction":"美国/北约","name":"第1步兵师「大红一师」","type":"步兵","cost":4,"operation_cost":1,"attack":3,"defense":5,"rarity":"特殊","effect":"守护。每个己方回合，首次有友方坦克移入前线后，修复本单位2点防御。","historical_anchor":"美国机械化步兵；单位代表战斗分队，并非整师同场。","fictional":false,"alternate_timeline":false},{"id":"N-06","faction":"美国/北约","name":"第1陆战师","type":"步兵","cost":4,"operation_cost":1,"attack":4,"defense":4,"rarity":"普通","effect":"部署：若己方控制前线，抽1张牌。","historical_anchor":"美国海军陆战队；冷战末期编制。","fictional":false,"alternate_timeline":false},{"id":"N-07","faction":"美国/北约","name":"英国伞兵分队","type":"步兵","cost":2,"operation_cost":1,"attack":2,"defense":3,"rarity":"普通","effect":"部署：若敌方控制前线，本单位永久攻击+1。","historical_anchor":"英国伞兵团冷战部队抽象。","fictional":false,"alternate_timeline":false},{"id":"N-08","faction":"美国/北约","name":"「回声」心灵侦察组","type":"步兵","cost":3,"operation_cost":1,"attack":1,"defense":4,"rarity":"特殊","effect":"烟幕。部署：情报1；锁定一支敌方单位。","historical_anchor":"原创架空；遥视研究不等于真实可用的心灵武器。","fictional":true,"alternate_timeline":fa